                            context.EvaluatedKeywordForProperty(false, 7, RequiredPropertyRecordIdNotPresent, "recordId"u8, "required"u8);
                        }
                        else
                        {
                            context.EvaluatedKeywordForProperty(true, 7, RequiredPropertyRecordIdPresent, "recordId"u8, "required"u8);
                        }

                        if ((requiredPropertyChildHandler_seenItems[RequiredOffsetForSchemaVersion] & RequiredBitForSchemaVersion) == 0)
                        {
                            context.EvaluatedKeywordForProperty(false, 8, RequiredPropertySchemaVersionNotPresent, "schemaVersion"u8, "required"u8);
                        }
                        else
                        {
                            context.EvaluatedKeywordForProperty(true, 8, RequiredPropertySchemaVersionPresent, "schemaVersion"u8, "required"u8);
                        }

                        if ((requiredPropertyChildHandler_seenItems[RequiredOffsetForSourceHash] & RequiredBitForSourceHash) == 0)
                        {
                            context.EvaluatedKeywordForProperty(false, 9, RequiredPropertySourceHashNotPresent, "sourceHash"u8, "required"u8);
                        }
                        else
                        {
                            context.EvaluatedKeywordForProperty(true, 9, RequiredPropertySourceHashPresent, "sourceHash"u8, "required"u8);
                        }
                    }
                }
            }

            internal static bool Evaluate(
                IJsonDocument parentDocument,
                int parentIndex,
                IJsonSchemaResultsCollector? resultsCollector = null)
            {
                JsonSchemaContext context = JsonSchemaContext.BeginContext(
                parentDocument,
                parentIndex,
                usingEvaluatedItems: false,
                usingEvaluatedProperties: true,
                resultsCollector: resultsCollector);
                try
                {
                    Evaluate(parentDocument, parentIndex, ref context);
                    context.EndContext();
                    return context.IsMatch;
                }
                finally
                {
                    context.Dispose();
                }
            }

